source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    result = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    fill_by_size = {(3, 3): 8, (5, 5): 4, (7, 7): 3}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or outside[r][c] or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                cr, cc = q.popleft()
                cells.append((cr, cc))
                for nr, nc in ((cr-1,cc), (cr+1,cc), (cr,cc-1), (cr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc] and not seen[nr][nc]:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            min_r = min(x[0] for x in cells); max_r = max(x[0] for x in cells)
            min_c = min(x[1] for x in cells); max_c = max(x[1] for x in cells)
            size = (max_r - min_r + 1, max_c - min_c + 1)
            color = fill_by_size[size]
            for cr, cc in cells:
                result[cr][cc] = color
    return result
'''
